//! Oracle tier: reads Goldmark artifacts regenerated by
//! `scripts/regen-fixtures.py` (see docs/FIXTURES.md).
#![cfg(feature = "oracle-fixtures")]
use d2_rs_text::markdown::text::Segment;
use serde::Deserialize;
use serde_json::{Value, json};

#[derive(Deserialize)]
#[serde(rename_all = "PascalCase")]
struct Request {
    source: String,
    segment: Segment,
    widths: Vec<isize>,
}
#[derive(Deserialize)]
struct Fixture {
    requests: Vec<Request>,
    results: Vec<Value>,
}

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}
fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

#[test]
fn pinned_goldmark_segment_methods() {
    let fixture: Fixture = serde_json::from_str(d2_rs_testdata::oracle_fixture!(
        "tests/fixtures/segments.json"
    ))
    .unwrap();
    assert_eq!(fixture.requests.len(), fixture.results.len());
    for (index, (r, expected)) in fixture.requests.iter().zip(&fixture.results).enumerate() {
        let source = unhex(&r.source);
        let s = r.segment;
        let widths: Vec<_> = r
            .widths
            .iter()
            .map(|w| s.trim_left_space_width(*w, &source))
            .collect();
        let mut concat = b"prefix".to_vec();
        s.concat_padding(&mut concat);
        let actual = json!({
            "value":hex(&s.value(&source)), "len":s.len(), "empty":s.is_empty(),
            "left":s.trim_left_space(&source), "right":s.trim_right_space(&source), "widths":widths,
            "start":s.with_start(s.stop), "stop":s.with_stop(s.start),
            "between":s.between(Segment::new(s.stop, s.stop)), "concat":hex(&concat),
        });
        assert_eq!(&actual, expected, "case {index}");
    }
}
